# Writing Task 1 practice bank.
# Each entry: dict(visual, title, desc, unit, data=[(series, category, value)], steps=[...], overview=[...])
# desc is the opening of the instructions; the standard ending is added by the builder.
# For map comparisons, steps are "Label|zone|feature" with zones NW N NE W C E SW S SE.
def bars(series, cats, rows):
    """rows[i][j] = value for cats[i], series[j]"""
    return [(s, c, v) for c, row in zip(cats, rows) for s, v in zip(series, row)]

